{
  "@context": {
    "@language": "en",
    "@vocab": "https://schema.org/",
    "cr": "http://mlcommons.org/croissant/",
    "dct": "http://purl.org/dc/terms/",
    "sc": "https://schema.org/"
  },
  "@type": "cr:TaskProblem",
  "conformsTo": "http://mlcommons.org/croissant/1.0",
  "@id": "[FILL IN THE BLANK: paper_id]-task",
  "name": "Early Training Evaluation Benchmarks for SLMs",
  "description": "Evaluate Small Language Models (SLMs) during early training stages on scientific knowledge acquisition, reasoning, and sensitivity to knowledge-intensive tasks.",
  "paper_id": "[FILL IN THE BLANK: paper_id]",

  "cr:input": [
    {
      "@type": "cr:FileObject",
      "name": "Input Dataset",
      "description": "Input dataset contains a single column 'id' with unique sample identifiers. Example values: 'sample_000', 'sample_001', 'sample_002'.",
      "encodingFormat": "text/csv",
      "contentUrl": "[FILL IN THE BLANK: dataset source URL]"
    }
  ],

  "cr:output": {
    "name": "predictions",
    "description": "Predictions are expected in a CSV file with two columns: 'id' (matching input IDs) and 'pred' (predicted values). Example values for 'pred': 0.6470268045601905, 0.35506678184339246.",
    "cr:schema": {
      "@type": "cr:RecordSet",
      "name": "prediction_schema",
      "field": [
        {
          "@type": "cr:Field",
          "name": "id",
          "dataType": "sc:Text",
          "description": "Unique identifier for each sample. Example values: 'sample_000', 'sample_001'."
        },
        {
          "@type": "cr:Field",
          "name": "pred",
          "dataType": "sc:Float",
          "description": "Predicted value for the sample. Example values: 0.6470268045601905, 0.35506678184339246."
        }
      ]
    }
  },

  "cr:implementation": {
    "cr:environment": {
      "language": "Python",
      "packages": ["numpy", "pandas", "scipy", "sklearn"]
    },
    "entryPoint": "solution.py",
    "interface": "predict(input_dir, output_dir)"
  },

  "cr:evaluation": {
    "primaryMetric": "Total Score",
    "metrics": ["Total Score", "Signal Quality", "Ranking Consistency", "Compliance Score"],
    "higherIsBetter": true,
    "notes": "Metrics are computed using Spearman correlation, mean squared error, and other statistical methods. Total Score is a weighted combination of Signal Quality (0.5), Ranking Consistency (0.1), and Compliance Score (0.4)."
  },

  "cr:execution": {
    "runtimeLimitSec": 600,
    "memoryLimitMb": 4096,
    "allowedExternalData": "unknown"
  },

  "open_questions": [
    "What is the original paper DOI?",
    "What is the dataset source URL?",
    "What is the paper ID?"
  ],

  "fill_in_the_blank": [
    "paper_id - reason it could not be determined from the bundle files",
    "cr:input[0].contentUrl - reason it could not be determined from the bundle files",
    "@id - reason it could not be determined from the bundle files"
  ]
}
